/* Generated by the module split. See README §開発の分担. */
import { C } from './palette.js';
import { S, GAME } from './state.js';
import { PRIO, spawn, N } from './sim.js';


/* ============================================================
   10. console log lines (real Falco rule names)
   ============================================================ */
const RULES_LOG = [
  ['Terminal shell in container', 2, 'user=root shell=bash parent=containerd-shim'],
  ['Drop and execute new binary in container', 0, 'exe=/tmp/.x parent=sh'],
  ['Read sensitive file untrusted', 1, 'file=/etc/shadow proc=cat'],
  ['Write below etc', 1, 'file=/etc/cron.d/pwn proc=sh'],
  ['Contact K8S API Server From Container', 2, 'connection=10.0.0.1:443 proc=curl'],
  ['Launch Privileged Container', 2, 'image=nginx:latest privileged=true'],
  ['Detect crypto miners using the Stratum protocol', 0, 'proc=xmrig port=3333'],
  ['Redirect STDOUT/STDIN to Network Connection in Container', 1, 'proc=bash fd=3'],
  ['Sudo Potential Privilege Escalation', 1, 'proc=sudoedit user=app'],
  ['Packet socket created in container', 3, 'proc=tcpdump'],
  ['Clear Log Activities', 1, 'file=/var/log/auth.log proc=shred'],
  ['Search Private Keys or Passwords', 2, 'proc=grep args=-r BEGIN RSA'],
  ['Change thread namespace', 3, 'proc=nsenter'],
  ['Non sudo setuid', 2, 'proc=node uid=0'],
  /* 4th element = plugin event source (not syscalls) → no syscall-side k8s.pod
     suffix, and these are the ONLY rules that can fire in kernel-less mode */
  ['K8s Secret Get Successfully', 2, 'ka.user=svc/deployer ka.target.name=db-creds ka.target.namespace=payments', 'k8saudit'],
  ['Create Privileged Pod', 0, 'ka.user=svc/ci ka.target.name=debug-pod ka.target.namespace=payments', 'k8saudit'],
  ['Attach/Exec Pod', 2, 'ka.user=alice@corp ka.target.name=api-7f9c ka.target.namespace=payments', 'k8saudit'],
  ['ClusterRole With Write Privileges Created', 1, 'ka.user=svc/ci ka.target.name=edit-all', 'k8saudit'],
  ['Console Login Without MFA', 1, 'aws.user=ops-admin aws.region=ap-northeast-1 mfa=false', 'cloudtrail'],
  ['Delete Bucket Encryption', 0, 'aws.user=svc/deploy aws.bucket=prod-artifacts', 'cloudtrail'],
  ['Put Bucket ACL Public Read/Write', 0, 'aws.user=svc/deploy aws.bucket=prod-logs acl=public-read-write', 'cloudtrail'],
  ['CloudTrail Trail Deleted', 0, 'aws.user=root aws.region=us-east-1 trail=org-trail', 'cloudtrail'],
  ['Okta User Account Locked', 3, 'okta.actor=bob@corp okta.attempts=8', 'okta'],
  ['Github Secret Pushed', 1, 'github.repo=corp/api github.user=carol type=aws_key', 'github']
];
const NS = ['payments','checkout','default','kube-system','ingress','data-eng'];
const PODS = ['api-7f9c','worker-2b1','nginx-5dd','etl-9ac','auth-3e8','cache-c17'];

const clog = document.getElementById('clog');
let logCooldown = 0, logQueue = [], dropCool = 0;
const metaQueue = [];          // falco's own messages (drops, exit, restart)

function nowTs(){
  const n = new Date();
  return `${String(n.getHours()).padStart(2,'0')}:${String(n.getMinutes()).padStart(2,'0')}`
       + `:${String(n.getSeconds()).padStart(2,'0')}.${String(n.getMilliseconds()).padStart(3,'0')}`;
}
function appendLine(html){
  const el = document.createElement('div');
  el.innerHTML = html;
  clog.appendChild(el);
  while(clog.children.length > 26) clog.removeChild(clog.firstChild);
}

/* syscall_event_drops.actions — the point being that `ignore` is a choice
   to be blind, and `exit` is a choice to fail loudly rather than silently. */
function onDrop(){
  const act = S.tune.dropAction;
  if(act === 'ignore') return;
  S.deadDrops++;
  if(act === 'exit' && !S.dead && S.deadDrops >= 15){ die(); return; }
  if(dropCool > 0) return;
  dropCool = 2.2;
  const n = S.counters.drop;
  if(act === 'log')
    metaQueue.push({cls:'kv', text:`falco: ${n} syscall event drops so far (actions: log)`});
  else
    metaQueue.push({cls:'p-err', text:`Critical Falco internal: syscall event drops — ${n} events lost (actions: alert)`});
}
function die(){
  S.dead = true;
  metaQueue.push({cls:'p-err',
    text:'falco: too many consecutive syscall event drops — actions: exit → agent stopped. 検知は止まりました。'});
}
function revive(){
  if(!S.dead) return;
  S.dead = false; S.deadDrops = 0;
  for(let i=0;i<N;i++) spawn(i, Math.random()*1.6);
  metaQueue.push({cls:'sys', text:'falco restarted — detection resumed'});
}

function emitLog(prio){
  if(logQueue.length > 6) return;
  logQueue.push(prio);
}
function flushLog(dt){
  logCooldown -= dt;
  dropCool -= dt;
  /* falco's own messages jump the queue — they are not rule matches */
  if(metaQueue.length){
    const m = metaQueue.shift();
    appendLine(`<span class="ts">${nowTs()}</span> <span class="${m.cls}">${m.text}</span>`);
  }
  if(logCooldown > 0 || !logQueue.length || S.dead) return;
  logCooldown = 0.42 + Math.random()*0.5;
  const prio = logQueue.shift();
  /* kernel-less: only plugin sources can fire.
     plain host: no API server, so no k8saudit rules either. */
  const pluginOnly = S.deploy === 'plugins';
  const noCluster  = S.deploy === 'host';
  const ok = r => (!pluginOnly || !!r[3]) && !(noCluster && r[3] === 'k8saudit');
  let pool = RULES_LOG.filter(r => r[1]===prio && ok(r));
  if(!pool.length) pool = RULES_LOG.filter(ok);
  if(!pool.length) pool = RULES_LOG;
  const r = pool[(Math.random()*pool.length)|0];
  const ts = nowTs();
  const p = PRIO[r[1]];
  const ns = NS[(Math.random()*NS.length)|0], pod = PODS[(Math.random()*PODS.length)|0];
  /* a plain host has container metadata but no Kubernetes metadata to enrich with */
  const ctx = r[3] ? r[2]
            : S.deploy === 'k8s' ? `${r[2]} k8s.ns=${ns} k8s.pod=${pod}`
            : `${r[2]} container.id=${(0x100000+((Math.random()*0xefffff)|0)).toString(16)}`;
  appendLine(`<span class="ts">${ts}</span> <span class="${p.cls}">${p.name}</span> ${r[0]} `+
             `<span class="kv">(${ctx})</span>`);
  if(S.mode==='sysdig' && Math.random()<0.3){
    appendLine(`<span class="ts">${ts}</span> <span class="sys">sysdig</span> `+
      `<span class="kv">policy=Sysdig Runtime Threat Detection · capture=stored · in-use CVE correlated</span>`);
  }
}

export {
  emitLog,
  flushLog,
  onDrop,
  die,
  revive,
  appendLine,
  nowTs,
  metaQueue
};
